def solve(s):
    """Run-length encoding for any iterable of characters.
    Returns a list of [char, count] pairs.
    If `s` is not iterable, returns an empty list.
    """
    try:
        it = iter(s)
    except TypeError:
        return []
    res = []
    try:
        prev = next(it)
    except StopIteration:
        return []
    count = 1
    for ch in it:
        if ch == prev:
            count += 1
        else:
            res.append([prev, count])
            prev = ch
            count = 1
    res.append([prev, count])
    return res

