def solve(s: str) -> int:
    """Convert a Roman numeral to an integer.
    Handles both uppercase and lowercase inputs, and ignores surrounding whitespace.
    Returns 0 for empty input.
    """
    if not s:
        return 0
    s = s.strip().upper()
    values = {'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000}
    total = 0
    prev = 0
    for ch in reversed(s):
